import React from 'react';
import CountUp from 'react-countup';
import { useInView } from 'react-intersection-observer';
import { motion } from 'framer-motion';
import { FiArrowRight, FiCode, FiGlobe, FiCheckCircle } from 'react-icons/fi';

const ProjectShowcaseBanner = () => {
  const [ref, inView] = useInView({
    threshold: 0.3,
    triggerOnce: true
  });

  const stats = [
    { 
      id: 1, 
      number: 12, 
      suffix: '+', 
      label: 'Completed Projects', 
      icon: <FiCheckCircle className="text-blue-300" />,
      duration: 2.5
    },
    { 
      id: 2, 
      number: 5, 
      label: 'Live Deployments', 
      icon: <FiGlobe className="text-indigo-300" />,
      duration: 2
    },
    { 
      id: 3, 
      number: 8, 
      label: 'React Solutions', 
      icon: <FiCode className="text-purple-300" />,
      duration: 1.5
    }
  ];

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.15,
        delayChildren: 0.3
      }
    }
  };

  const itemVariants = {
    hidden: { y: 30, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: {
        type: 'spring',
        stiffness: 120,
        damping: 12,
        mass: 0.5
      }
    }
  };

  const cardHover = {
    y: -8,
    transition: { type: 'spring', stiffness: 300, damping: 10 }
  };

  const buttonHover = {
    scale: 1.03,
    boxShadow: '0 10px 25px -5px rgba(255, 255, 255, 0.2)',
    transition: { duration: 0.3 }
  };

  const buttonTap = {
    scale: 0.98,
    transition: { duration: 0.2 }
  };

  return (
    <div 
      ref={ref}
      className="w-full bg-gradient-to-br from-blue-600 via-indigo-700 to-purple-800 py-12 md:py-16 px-4 sm:px-6 lg:px-8 relative overflow-hidden"
    >
      {/* Decorative elements */}
      <div className="absolute inset-0 opacity-10">
        <div className="absolute top-1/4 left-1/4 w-32 h-32 rounded-full bg-white blur-xl"></div>
        <div className="absolute bottom-1/3 right-1/3 w-40 h-40 rounded-full bg-indigo-400 blur-xl"></div>
      </div>
      
      <motion.div
        className="max-w-7xl mx-auto relative z-10"
        initial="hidden"
        animate={inView ? "visible" : "hidden"}
        variants={containerVariants}
      >
        <div className="text-center mb-10">
          <motion.h2 
            className="text-3xl md:text-4xl font-bold text-white mb-4"
            variants={itemVariants}
          >
            Crafting Digital Excellence
          </motion.h2>
          <motion.p 
            className="text-blue-100/90 text-lg max-w-2xl mx-auto leading-relaxed"
            variants={itemVariants}
          >
            Innovative solutions that drive results and create memorable experiences
          </motion.p>
        </div>

        <motion.div 
          className="grid grid-cols-1 md:grid-cols-3 gap-6 md:gap-8"
          variants={containerVariants}
        >
          {stats.map((stat) => (
            <motion.div
              key={stat.id}
              className="bg-white/5 backdrop-blur-md rounded-2xl p-6 md:p-8 text-center border border-white/10 shadow-xl hover:shadow-2xl transition-all duration-300"
              variants={itemVariants}
              whileHover={cardHover}
            >
              <div className="flex justify-center text-4xl mb-4">
                {stat.icon}
              </div>
              <div className="text-4xl md:text-5xl font-bold text-white mb-2">
                {inView ? (
                  <CountUp
                    end={stat.number}
                    suffix={stat.suffix || ''}
                    duration={stat.duration}
                    delay={0.5}
                    className="font-extrabold bg-clip-text text-transparent bg-gradient-to-r from-blue-300 to-white"
                  />
                ) : (
                  <span className="font-extrabold bg-clip-text text-transparent bg-gradient-to-r from-blue-300 to-white">
                    0{stat.suffix || ''}
                  </span>
                )}
              </div>
              <div className="text-blue-100/90 text-lg font-medium">
                {stat.label}
              </div>
            </motion.div>
          ))}
        </motion.div>

        <motion.div 
          className="mt-12 text-center"
          variants={itemVariants}
        >
          <motion.button 
            className="px-8 py-3 bg-white text-blue-600 font-semibold rounded-full hover:bg-blue-50 transition-all duration-300 shadow-lg flex items-center gap-2 mx-auto"
            whileHover={buttonHover}
            whileTap={buttonTap}
          >
            Explore My Portfolio
            <FiArrowRight className="transition-transform duration-300 group-hover:translate-x-1" />
          </motion.button>
        </motion.div>
      </motion.div>
    </div>
  );
};

export default ProjectShowcaseBanner;