import { FaReact, FaNodeJs, FaSass } from 'react-icons/fa';
import { SiTailwindcss, SiMongodb, SiExpress, SiTypescript, SiNextdotjs, SiRedux } from 'react-icons/si';
import { motion } from 'framer-motion';
import styled from 'styled-components';

const techStack = [
  { icon: <FaReact size={28} />, name: 'React', color: '#61DAFB' },
  { icon: <SiNextdotjs size={28} />, name: 'Next.js', color: '#000000' },
  { icon: <SiTypescript size={28} />, name: 'TypeScript', color: '#3178C6' },
  { icon: <FaNodeJs size={28} />, name: 'Node.js', color: '#339933' },
  { icon: <SiExpress size={28} />, name: 'Express', color: '#000000' },
  { icon: <SiMongodb size={28} />, name: 'MongoDB', color: '#47A248' },
  { icon: <SiTailwindcss size={28} />, name: 'Tailwind', color: '#38B2AC' },
  { icon: <FaSass size={28} />, name: 'Sass', color: '#CC6699' },
  { icon: <SiRedux size={28} />, name: 'Redux', color: '#764ABC' },
];

const TechStackGrid = () => {
  return (
    <TechStackContainer>
      <Title>My <Highlight>Tech Stack</Highlight></Title>
      <Subtitle>Technologies I've mastered and trust for production-grade applications</Subtitle>
      <Grid>
        {techStack.map((tech, index) => (
          <TechItem 
            key={tech.name}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.1, duration: 0.5 }}
            whileHover={{ 
              scale: 1.05,
              boxShadow: `0 10px 25px ${tech.color}20`
            }}
            color={tech.color}
          >
            <IconContainer>
              {tech.icon}
              <TechHoverEffect color={tech.color} />
            </IconContainer>
            <TechName>{tech.name}</TechName>
          </TechItem>
        ))}
      </Grid>
    </TechStackContainer>
  );
};

// Styled Components
const TechStackContainer = styled.div`
  max-width: 900px;
  margin: 4rem auto;
  padding: 0 1.5rem;
`;

const Title = styled.h2`
  text-align: center;
  margin-bottom: 0.5rem;
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--text-dark);
  position: relative;
  line-height: 1.2;
`;

const Highlight = styled.span`
  background: linear-gradient(90deg, #6366f1, #8b5cf6);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
`;

const Subtitle = styled.p`
  text-align: center;
  color: var(--text-secondary);
  margin-bottom: 3rem;
  font-size: 1rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.6;
`;

const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
  gap: 2rem;
  place-items: center;
`;

const TechItem = styled(motion.div)`
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  padding: 1.75rem 1rem;
  border-radius: 16px;
  background: ${({ theme }) => theme.cardBackground || 'white'};
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.03), 0 1px 3px rgba(0, 0, 0, 0.06);
  width: 100%;
  cursor: default;
  position: relative;
  overflow: hidden;
  border: 1px solid ${({ theme }) => theme.cardBorder || '#f3f4f6'};
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  
  svg {
    color: ${props => props.color};
    transition: all 0.3s ease;
    position: relative;
    z-index: 2;
  }
`;

const IconContainer = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 64px;
  height: 64px;
  position: relative;
`;

const TechHoverEffect = styled.div`
  position: absolute;
  width: 100%;
  height: 100%;
  background: ${props => props.color}10;
  border-radius: 50%;
  filter: blur(12px);
  opacity: 0;
  transition: opacity 0.3s ease;
  
  ${TechItem}:hover & {
    opacity: 1;
  }
`;

const TechName = styled.span`
  font-weight: 600;
  color: var(--text-secondary);
  font-size: 0.95rem;
  text-align: center;
  position: relative;
  z-index: 2;
`;

export default TechStackGrid;