import { motion } from 'framer-motion';
import { FaGithub, FaExternalLinkAlt } from 'react-icons/fa';
import project1 from '../assets/images/project1.jpg';
import project2 from '../assets/images/project2.jpg';
import project3 from '../assets/images/project3.jpg';
import TechStackGrid from "../components/project/TechStackGrid";
import ProjectFilter from "../components/project/ProjectFilter";
import ProjectShowcaseBanner from "../components/project/ProjectShowcaseBanner";

const Projects = () => {
 const projects = [
  {
    title: "Fremantle Taxi Service",
    description: "A responsive taxi booking website with calendar, contact, and modern UI for seamless user experience.",
    image: project1,
    tags: ["React", "Framer Motion", "CSS3", "Responsive Design"],
    github: "", // Code public nahi to blank
    live: "https://fremantletaxiservice.com/"
  },
  {
    title: "QuantumStack Company Site",
    description: "A modern company website built with sleek design, services section, and responsive layout.",
    image: project2,
    tags: ["React", "Tailwind CSS", "Responsive Design"],
    github: "", // Code public nahi to blank
    live: "https://quantumstackai.com/"
  },
  {
    title: "MobileMart (E-Commerce Demo)",
    description: "A basic e-commerce website for mobile devices built with React and deployed using GitHub Pages.",
    image: project3,
    tags: ["React", "CSS3", "GitHub Pages"],
    github: "https://github.com/shahzaib1535/mobliemart",
    live: "https://shahzaib1535.github.io/mobliemart/"
  }
];


  return (
    <>
        <section id="projects" className="py-20 bg-gradient-to-br from-gray-900 to-gray-800 text-white">
      <div className="container mx-auto px-4 max-w-6xl">
        {/* Section Header */}
        <motion.div
          initial={{ opacity: 0, y: 50 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          viewport={{ once: true }}
          className="text-center mb-16"
        >
          <h2 className="text-4xl font-bold mb-2 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-600">
            My Projects
          </h2>
          <p className="text-xl text-gray-300">Some of my recent work</p>
        </motion.div>

        {/* Projects Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {projects.map((project, index) => (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 50 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: index * 0.1 }}
              viewport={{ once: true }}
              whileHover={{ y: -10 }}
              className="bg-gray-800 rounded-xl overflow-hidden shadow-2xl hover:shadow-purple-500/20 transition-all duration-300"
            >
              {/* Project Image with Hover Effect */}
              <motion.div 
                className="relative overflow-hidden h-48"
                whileHover={{ scale: 1.05 }}
                transition={{ duration: 0.3 }}
              >
                <img 
                  src={project.image} 
                  alt={project.title} 
                  className="w-full h-full object-cover"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent opacity-0 hover:opacity-100 transition-opacity duration-300 flex items-end p-4">
                  <div className="flex space-x-4">
                    <motion.a 
                      href={project.github} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      whileHover={{ scale: 1.1 }}
                      className="bg-gray-800 p-2 rounded-full hover:bg-gray-700 transition-colors"
                    >
                      <FaGithub className="text-xl" />
                    </motion.a>
                    <motion.a 
                      href={project.live} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      whileHover={{ scale: 1.1 }}
                      className="bg-gray-800 p-2 rounded-full hover:bg-gray-700 transition-colors"
                    >
                      <FaExternalLinkAlt className="text-xl" />
                    </motion.a>
                  </div>
                </div>
              </motion.div>

              {/* Project Content */}
              <div className="p-6">
                <h3 className="text-xl font-bold mb-2 text-blue-400">{project.title}</h3>
                <p className="text-gray-300 mb-4">{project.description}</p>
                
                {/* Tags */}
                <div className="flex flex-wrap gap-2">
                  {project.tags.map((tag, i) => (
                    <motion.span 
                      key={i}
                      whileHover={{ scale: 1.05 }}
                      className="text-xs bg-gray-700 text-blue-300 px-3 py-1 rounded-full"
                    >
                      {tag}
                    </motion.span>
                  ))}
                </div>
              </div>
            </motion.div>
          ))}
        </div>

        {/* View More Button (Optional) */}
        <motion.div
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          transition={{ delay: 0.5 }}
          viewport={{ once: true }}
          className="text-center mt-12"
        >
          <motion.a
            href="#"
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            className="inline-block px-6 py-3 bg-gradient-to-r from-purple-600 to-blue-500 rounded-lg font-medium shadow-lg hover:from-purple-700 hover:to-blue-600 transition-all"
          >
            View All Projects
          </motion.a>
        </motion.div>
      </div>
    </section>

    <ProjectFilter/>

    <TechStackGrid/>

    <ProjectShowcaseBanner/>
    </>

  );
};

export default Projects;